 IF EXISTS(SELECT 1 FROM tradeskill_recipe_entries a JOIN tradeskill_recipe r ON r.id=a.recipe_id WHERE a.item_id=53474 AND a.componentcount>0 AND a.iscontainer=0 AND r.id<>3096823 AND(SELECT SUM(e.componentcount)FROM tradeskill_recipe_entries e WHERE e.recipe_id=r.id AND e.iscontainer=0)=4 AND(SELECT COALESCE(SUM(e.componentcount),0)FROM tradeskill_recipe_entries e WHERE e.recipe_id=r.id AND e.iscontainer=0 AND e.item_id=13087)=1 AND(SELECT COALESCE(SUM(e.componentcount),0)FROM tradeskill_recipe_entries e WHERE e.recipe_id=r.id AND e.iscontainer=0 AND e.item_id=15961)=1 AND(SELECT COALESCE(SUM(e.componentcount),0)FROM tradeskill_recipe_entries e WHERE e.recipe_id=r.id AND e.iscontainer=0 AND e.item_id=25759)=1 AND(SELECT COALESCE(SUM(e.componentcount),0)FROM tradeskill_recipe_entries e WHERE e.recipe_id=r.id AND e.iscontainer=0 AND e.item_id=53474)=1) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC219 all-state full input collision'; END IF;
 DROP TEMPORARY TABLE rrc219_peer_entries;
 DROP TEMPORARY TABLE rrc219_peer_recipes;
 DROP TEMPORARY TABLE rrc219_entries;
 DROP TEMPORARY TABLE rrc219_recipes;
 DROP TEMPORARY TABLE rrc219_items;
 COMMIT;
 SET own_transaction=FALSE;
 SELECT 'RRC219' AS batch,already_present AS previous_recipe_count,recipes_before AS recipes_before,(SELECT COUNT(*) FROM tradeskill_recipe) AS recipes_after,entries_before AS entries_before,(SELECT COUNT(*) FROM tradeskill_recipe_entries) AS entries_after,@@in_transaction AS in_transaction;
END//
DELIMITER ;
